import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:go_router/go_router.dart';
import '../../shared/providers.dart';
class ProfileScreen extends ConsumerWidget{const ProfileScreen({super.key});@override Widget build(BuildContext context,WidgetRef ref)=>Scaffold(appBar:AppBar(title:const Text('Profile')),body:FutureBuilder(future:ref.read(apiProvider).dio.get<Map<String,dynamic>>('/profiles/me'),builder:(context,snapshot){if(!snapshot.hasData)return const Center(child:CircularProgressIndicator());final user=snapshot.data!.data!;return ListView(padding:const EdgeInsets.all(18),children:[const CircleAvatar(radius:42,child:Icon(Icons.person,size:42)),const SizedBox(height:12),Text(user['displayName'] as String,textAlign:TextAlign.center,style:Theme.of(context).textTheme.titleLarge?.copyWith(fontWeight:FontWeight.w700)),Text(user['phoneE164'] as String,textAlign:TextAlign.center,style:const TextStyle(color:Colors.black54)),const SizedBox(height:24),Card(child:Column(children:[ListTile(leading:const Icon(Icons.language),title:const Text('Language'),trailing:const Text('English')),const Divider(height:1),ListTile(leading:const Icon(Icons.privacy_tip_outlined),title:const Text('Privacy & security')),const Divider(height:1),ListTile(leading:const Icon(Icons.help_outline),title:const Text('Help & support'))])),const SizedBox(height:18),OutlinedButton.icon(onPressed:()async{await ref.read(sessionProvider).clear();if(context.mounted)context.go('/login');},icon:const Icon(Icons.logout),label:const Text('Sign out'))]);}));}

